effect.script:
function hash11(x){
let s = Math.sin(x * 127.1 + 311.7) * 43758.5453123;
return s - Math.floor(s);
}

function clamp01(x){
if( x < 0.0 ) return 0.0;
if( x > 1.0 ) return 1.0;
return x;
}

function animate(env, el, p){
let base = el.text;
let n = base.length;
if( n < 1 ) return el;

// ---- build progress -----------------------------------------------------
let t   = env.time * env.duration;
let t0  = p.delay * env.duration;
let dur = Math.max(1e-3, p.buildTime);
let u = clamp01((t - t0) / dur);

// Stagger spreads the per-character windows across the build. The LAST key
// always lands exactly at u = 1, so Build Time is the true total duration
// whatever the stagger.
let st  = Math.max(0.0, Math.min(0.95, p.stagger));
let win = Math.max(1e-3, 1.0 - st);

let a0 = Math.min(p.start, p.end);
let a1 = Math.max(p.start, p.end);
let lo = Math.floor(n * a0);
let hi = Math.ceil(n * a1);
if( hi <= lo ) return el;
let span = Math.max(1, hi - lo - 1);

let ord = Math.round(p.order);
let ez  = Math.round(p.ease);
let rm  = Math.round(p.revealMode);
let fc  = Math.round(p.fillChar);
let scr = Math.round(p.scrambleCharset);
let cc  = Math.round(p.cursorChar);

// ---- glyph pools --------------------------------------------------------
let scs = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
if( scr == 1 ){ scs = "0123456789"; }
else if( scr == 2 ){ scs = "0123456789ABCDEF"; }
else if( scr == 3 ){ scs = "\u2588\u2593\u2592\u2591\u25A0\u25AA\u25AB"; }
else if( scr == 4 ){ scs = "!@#$%^&*()_+-=<>/\\|"; }

let fch = " ";
if( fc == 1 ){ fch = "\u00B7"; }
else if( fc == 2 ){ fch = "_"; }
else if( fc == 3 ){ fch = "\u2588"; }
else if( fc == 4 ){ fch = "*"; }
else if( fc == 5 ){ fch = "#"; }

let cursorChar = "";
if( cc == 1 ){ cursorChar = "_"; }
else if( cc == 2 ){ cursorChar = "\u2588"; }
else if( cc == 3 ){ cursorChar = "\u258C"; }
else if( cc == 4 ){ cursorChar = "|"; }
else if( cc == 5 ){ cursorChar = "\u25AF"; }

// ---- reverse out --------------------------------------------------------
// u is already clamped to 1, so subtracting the collapse gives a clean
// tear-down after the hold.
let prog = u;
if( p.reverseOut ){
let v = clamp01((t - p.outStart * env.duration) / Math.max(1e-3, p.outDur));
prog = clamp01(u - v);
}

// ---- word map (needed by Word by Word) ----------------------------------
let wid = [];
let words = 0;
let prevSpace = true;
for( let i = 0; i < n; i = i + 1 ){
let sp = base.charAt(i) == " ";
if( !sp && prevSpace ){ words = words + 1; }
wid.push(words > 0 ? words - 1 : 0);
prevSpace = sp;
}
let wtot = Math.max(1, words);

let out = "";
for( let i = 0; i < n; i = i + 1 ){
let ch = base.charAt(i);
if( i >= lo && i < hi ){
// Order key: where this character sits in the assembly sequence.
let uu = (i - lo) / span;
let o;
if( ord < 1 ){ o = uu; }
else if( ord < 2 ){ o = 1.0 - uu; }
else if( ord < 3 ){ o = Math.abs(uu * 2.0 - 1.0); }
else if( ord < 4 ){ o = 1.0 - Math.abs(uu * 2.0 - 1.0); }
else if( ord < 5 ){ o = hash11(i * 3.7 + p.seed * 11.3); }
else { o = wid[i] / wtot; }

let local = clamp01((prog - o * st) / win);

if( ez == 1 ){ local = local * local * (3.0 - 2.0 * local); }
else if( ez == 2 ){ local = local * local; }
else if( ez == 3 ){ local = 1.0 - (1.0 - local) * (1.0 - local); }
else if( ez == 4 ){ local = local < 0.5 ? 0.0 : 1.0; }

if( local > 0.999 ){
out = out + ch;
} else if( ch == " " ){
out = out + " ";
} else if( rm < 1 ){
// Typewriter - the slot is simply empty.
} else if( rm < 2 ){
// Placeholder Wipe - a glyph holds the slot so nothing reflows.
if( fc == 6 ){
out = out + scs.charAt(Math.floor(hash11(i * 5.1 + p.seed) * scs.length) % scs.length);
} else if( fc == 7 ){
out = out + scs.charAt(Math.floor(hash11(i * 5.1 + p.seed) * 10.0) % 10);
} else {
out = out + fch;
}
} else {
// Scramble - unrevealed slots boil through the pool on a fixed frame clock.
let fr = Math.floor(t * 24.0);
let gi = Math.floor(hash11(i * 7.9 + p.seed * 3.3 + fr) * scs.length);
if( gi > scs.length - 1 ){ gi = scs.length - 1; }
if( gi < 0 ){ gi = 0; }
out = out + scs.charAt(gi);
}
} else {
out = out + ch;
}
}

// ---- cursor -------------------------------------------------------------
if( p.cursor && rm < 1 && cursorChar.length > 0 ){
let tail = out.replace(/\s+$/, "");
if( tail.length < 1 || tail.charAt(tail.length - 1) != cursorChar ){
out = tail + cursorChar;
} else {
out = tail;
}
}

el.text = out;
return el;
}
